def solve(grid):
    R = len(grid)
    C = len(grid[0])
    out_R = R * 2
    out_C = C * 2
    output = [[0 for _ in range(out_C)] for _ in range(out_R)]

    # Top-left quadrant is the input
    for r in range(R):
        for c in range(C):
            output[r][c] = grid[r][c]

    # Mirror horizontally for the top-right quadrant
    for r in range(R):
        for c in range(C):
            output[r][C + c] = grid[r][C - 1 - c]

    # Mirror vertically for the bottom-left quadrant
    for r in range(R):
        for c in range(C):
            output[R + r][c] = grid[R - 1 - r][c]

    # Mirror both for the bottom-right quadrant
    for r in range(R):
        for c in range(C):
            output[R + r][C + c] = grid[R - 1 - r][C - 1 - c]

    return output

